            # Deterministically, rebuild mappings for all remaining routes (keeps code simple & safe).
            cust_to_route = {}
            cust_to_pos = {}
            for ri, r in enumerate(routes):
                for pi, c in enumerate(r):
                    cust_to_route[c] = ri
                    cust_to_pos[c] = pi

            # Early stop if already small enough
            if len(routes) <= hint:
                break

    # --- End constructive edit ---

    # Existing merge_phase and improvements kept; but slightly reduced iterations for stability
    def attempt_merge(a, b):
        ra, rb = a, b
        base = route_cost(ra) + route_cost(rb)

        def try_concat(x, y):
            if route_load(x) + route_load(y) > capacity:
                return None
            merged = x + y
            newc = route_cost(merged)
            if newc < base - 1e-9:
                return merged
            return None

        merged = try_concat(ra, rb)
        if merged is not None:
            return merged
        merged = try_concat(ra, list(reversed(rb)))
        if merged is not None:
            return merged
        merged = try_concat(list(reversed(ra)), rb)
        if merged is not None:
            return merged
        merged = try_concat(list(reversed(ra)), list(reversed(rb)))
        if merged is not None:
            return merged
        return None

    def savings_key(i, j):
        ri, rj = routes[i], routes[j]
        if not ri or not rj:
            return -10**18
        if route_load(ri) + route_load(rj) > capacity:
            return -10**18
        base = route_cost(ri) + route_cost(rj)
        gains = []
        candidates = [
            (ri, rj),
            (ri, list(reversed(rj))),
            (list(reversed(ri)), rj),
            (list(reversed(ri)), list(reversed(rj))),
        ]
        best = -10**18
        for x, y in candidates:
            if route_load(x) + route_load(y) > capacity:
                continue
            newc = route_cost(x + y)
            gain = base - newc
            if gain > best:
                best = gain
        return best

    def merge_phase():
        nonlocal routes
        for _ in range(4):  # focused tweak: fewer passes to prevent over-merging instability
            if len(routes) <= hint or len(routes) <= 1:
                break
            best_i, best_j, best_merged, best_gain = None, None, None, 0
            m = len(routes)
            for i in range(m):
                for j in range(m):
                    if i == j:
                        continue
                    if len(routes) <= hint:
                        break
                    if route_load(routes[i]) + route_load(routes[j]) > capacity:
                        continue
                    gain = savings_key(i, j)
                    if gain <= 1e-9:
                        continue
                    merged = attempt_merge(routes[i], routes[j])
                    if merged is not None:
                        if gain > best_gain or (gain == best_gain and (i, j) < (best_i, best_j)):
                            best_i, best_j, best_merged, best_gain = i, j, merged, gain
                if len(routes) <= hint:
                    break
            if best_merged is None:
                break
            i, j = best_i, best_j
            if i > j:
                routes.pop(i)
                routes.pop(j)
            else:
                routes.pop(j)
                routes.pop(i)
            routes.append(best_merged)

    merge_phase()

    # Intra-route 2-opt (kept)
    def two_opt_intra(r):
        n = len(r)
        if n < 4:
            return r
        iters = 0
        while iters < 10:
            iters += 1
            base = route_cost(r)
            improved = False
            n = len(r)
            for i in range(n - 1):
                for k in range(i + 2, n):
                    newr = r[:i] + list(reversed(r[i:k + 1])) + r[k + 1:]
                    if route_cost(newr) + 1e-9 < base:
                        r = newr
                        improved = True
                        break
                if improved:
                    break
            if not improved:
                break
        return r

    for idx in range(len(routes)):
        routes[idx] = two_opt_intra(routes[idx])

    # Inter-route relocate (kept, but safer: recompute loads/costs after pop)
    def relocate_phase():
        nonlocal routes
        m = len(routes)
        for _ in range(3):
            improved_any = False
            loads = [route_load(r) for r in routes]
            costs = [route_cost(r) for r in routes]
            m = len(routes)
            for i in range(m):
                if i >= len(routes):
                    break
                ri = routes[i]
                if len(ri) <= 1:
                    continue
                for pos in range(len(ri)):
                    cust = ri[pos]
                    best = None  # (delta, j, new_ri, new_rj)
                    for j in range(len(routes)):
                        if j == i:
                            continue
                        if loads[j] + demands[cust] > capacity:
                            continue
                        rj = routes[j]
                        new_ri = ri[:pos] + ri[pos + 1:]
                        base = costs[i] + costs[j]
                        # try deterministic insertion positions
                        for ins in range(len(rj) + 1):
                            if ins == 0:
                                new_rj = [cust] + rj
                            elif ins == len(rj):
                                new_rj = rj + [cust]
                            else:
                                new_rj = rj[:ins] + [cust] + rj[ins:]
                            new_cost = route_cost(new_ri) + route_cost(new_rj)
                            delta = base - new_cost
                            if delta > 1e-9:
                                if best is None or delta > best[0]:
                                    best = (delta, j, new_ri, new_rj)
                    if best is not None:
                        _, j, new_ri, new_rj = best
                        routes[i] = new_ri
                        routes[j] = new_rj
                        if not routes[i]:
                            routes.pop(i)
